const fs = require('fs');
const esbuild = require('esbuild');

/**
 * Extract the maplibre-gl web worker code and save it for bundling.
 *
 * maplibre-gl v6 no longer includes this code in a UMD bundle, so we have to
 * grab it and shape it in such a way that it can be included in our bundle.
 * Save the worker into one standalone script and export that script
 * as a string. `src/plots/map/map.js` turns the string into a blob URL and
 * hands the URL to `maplibregl.setWorkerUrl`.
 *
 * @param pathIn - Path to the maplibre-gl worker entry point
 * @param pathOut - Path of the CommonJS module to write
 */
module.exports = (pathIn, pathOut) => {
    const { outputFiles } = esbuild.buildSync({
        entryPoints: [pathIn],
        bundle: true,
        write: false,
        format: 'esm',
        platform: 'browser',
        target: 'es2020',
        minify: true,
        logLevel: 'warning'
    });

    const source = JSON.stringify(outputFiles[0].text);

    fs.writeFileSync(
        pathOut,
        `'use strict';\n\n// Generated by tasks/util/bundle_maplibre_worker.js - do not edit.\nmodule.exports = ${source};\n`
    );
};
